#!/usr/bin/env bash
set -euo pipefail

# اسکریپت اعمال پچ رفع باگ تایمر (Countdown) در App.js
# این اسکریپت را در ریشه‌ی ریپوی محلی پروژه (جایی که پوشه .git وجود دارد) اجرا کنید:
#   bash fix-timer-bug.sh

if [ ! -d ".git" ]; then
  echo "خطا: این پوشه یک ریپوی گیت نیست. اسکریپت را داخل ریشه پروژه (کنار پوشه .git) اجرا کنید." >&2
  exit 1
fi

if [ ! -f "App.js" ]; then
  echo "خطا: فایل App.js در ریشه پروژه پیدا نشد." >&2
  exit 1
fi

cp App.js "App.js.bak.$(date +%Y%m%d%H%M%S)"
echo "نسخه فعلی App.js به‌عنوان بکاپ ذخیره شد."

base64 -d > App.js <<'APP_JS_B64_EOF'

APP_JS_B64_EOF

echo "App.js با نسخه اصلاح‌شده جایگزین شد."

git add App.js
git commit -m "fix: resolve countdown timer start bug (stale state in toggleTimer)"
git push

echo "پوش با موفقیت انجام شد."
